{"command": "cat <<'PY' > /tmp/probe2.py
import subprocess,re,os
os.makedirs('/tmp/probe2',exist_ok=True); os.chdir('/tmp/probe2')
def run(name,e,rep,extra=[]):
    open(name,'w').close()
    r=subprocess.run(['/workspace/executable','regex','--color','always']+extra+[e,rep,name],capture_output=True,text=True)
    out=[]
    for ln in r.stdout.split('\n'):
        if 'DRY' in ln or not ln.strip(): continue
        parts=re.split(r'(\x1b\[[0-9;]*m)',ln); cur=None;buf=[]
        for p in parts:
            if p.startswith('\x1b['): cur={'0':None,'1':'B','32':'G','1;31':'R','38;5;8':'D'}.get(p[2:-1],p[2:-1])
            else:
                if p: buf.append(('<%s>%s<'%(cur,p)) if cur else p)
        out.append(''.join(buf))
    return ' | '.join(out)
cases=[
 ('aab','a','Xa',[]),   # target Xaab
 ('aba','a','Xa',[]),   # target Xaba
 ('abc','b','Xb',[]),   # target aXbc
 ('abc','b','bX',[]),   # target abXc
 ('abab','b','bb',['-l','1']), # target abbab
 ('abab','b','bb',['-l','2']),
 ('abc','a','Xa',[]),
 ('aaaa','a','Xa',[]),
 ('aab','a','aa',[]),
 ('abab','a','aa',['-l','1']),
]
for c in cases:
    print('src=%r e=%r rep=%r %s'%(c[0],c[1],c[2],c[3]),'->',run(*c))
PY
python3 /tmp/probe2.py"}

