use std::fmt;
use std::io;
use std::path::PathBuf;

use crate::style::{dim, red};
use crate::ops::Operation;

#[derive(Debug)]
pub enum RnrError {
    /// Two or more operations produce the same target name.
    SameName(Vec<(String, String)>),
    /// The target of an operation already exists on disk.
    Conflict(Operation),
    /// The operations cannot be ordered so that every rename is safe.
    SortingProblem,
    /// The provided regular expression is not valid.
    BadExpression(String),
    /// The dump file could not be opened.
    OpenFile(PathBuf),
    /// The dump file could not be parsed.
    ParseJson(PathBuf),
    /// The dump file could not be written.
    CreateFile(PathBuf),
    /// Renaming failed.
    Rename(String, io::Error),
}

impl fmt::Display for RnrError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            RnrError::SameName(conflicts) => {
                let mut listing = String::new();
                for (a, b) in conflicts {
                    listing.push_str(&red(&format!("\n{}\n{}\n", a, b)));
                }
                write!(f, "Files will have the same name\n{}", red(&listing))
            }
            RnrError::Conflict(op) => write!(
                f,
                "Conflict with existing path {}",
                red(&format!("{} -> {}", op.source.display(), op.target.display()))
            ),
            RnrError::SortingProblem => write!(f, "Cannot solve sorting problem.{}", red("")),
            RnrError::BadExpression(msg) => write!(f, "Bad expression provided\n\n{}", red(msg)),
            RnrError::OpenFile(p) => write!(f, "Cannot open/read file {}", red(&p.display().to_string())),
            RnrError::ParseJson(p) => write!(f, "Cannot parse JSON file {}", red(&p.display().to_string())),
            RnrError::CreateFile(p) => write!(f, "Cannot create file {}", red(&p.display().to_string())),
            RnrError::Rename(op, e) => write!(
                f,
                "Cannot rename {}",
                red(&format!("{}\n{}", op, e))
            ),
        }
    }
}
EOF
cat > src/style.rs <<'EOF'
use std::sync::atomic::{AtomicBool, Ordering};

static ENABLED: AtomicBool = AtomicBool::new(false);

/// Enable or disable ANSI colour output globally.
pub fn set_enabled(on: bool) {
    ENABLED.store(on, Ordering::Relaxed);
}

pub fn enabled() -> bool {
    ENABLED.load(Ordering::Relaxed)
}

fn wrap(code: &str, s: &str) -> String {
    if enabled() {
        format!("\x1b[{}m{}\x1b[0m", code, s)
    } else {
        s.to_string()
    }
}

/// Grey (256 colour index 8) used for the original name.
pub fn dim(s: &str) -> String {
    wrap("38;5;8", s)
}

pub fn green(s: &str) -> String {
    wrap("32", s)
}

pub fn red(s: &str) -> String {
    wrap("31", s)
}

pub fn bold_red(s: &str) -> String {
    wrap("1;31", s)
}

pub fn bold(s: &str) -> String {
    wrap("1", s)
}
EOF
