use regex::{Captures, Regex};

use crate::ascii::to_ascii;
use crate::ops::Operation;

/// Transformation applied to replacement pieces.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Transform {
    Upper,
    Lower,
    Ascii,
}

impl Transform {
    pub fn apply(&self, text: &str) -> String {
        match self {
            Transform::Upper => text.to_uppercase(),
            Transform::Lower => text.to_lowercase(),
            Transform::Ascii => to_ascii(text),
        }
    }
}

/// One part of a replacement string: literal text or a capture group reference.
#[derive(Debug, PartialEq)]
pub enum Piece {
    Lit(String),
    Group(String),
}

fn is_name_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_'
}

/// Split a replacement into literal chunks and group references, mirroring the
/// expansion rules of the regex crate.
pub fn parse_replacement(rep: &str) -> Vec<Piece> {
    let mut pieces: Vec<Piece> = Vec::new();
    let mut lit = String::new();
    let mut chars = rep.chars().peekable();
    macro_rules! flush {
        () => {
            if !lit.is_empty() {
                pieces.push(Piece::Lit(std::mem::take(&mut lit)));
            }
        };
    }
    while let Some(c) = chars.next() {
        if c != '$' {
            lit.push(c);
            continue;
        }
        match chars.peek() {
            None => lit.push('$'),
            Some('$') => {
                chars.next();
                lit.push('$');
            }
            Some('{') => {
                chars.next();
                let mut name = String::new();
                let mut closed = false;
                while let Some(&c2) = chars.peek() {
                    if c2 == '}' {
                        chars.next();
                        closed = true;
                        break;
                    }
                    name.push(c2);
                    chars.next();
                }
                if closed {
                    flush!();
                    pieces.push(Piece::Group(name));
                } else {
                    lit.push('$');
                    lit.push('{');
                    lit.push_str(&name);
                }
            }
            Some(&c2) if is_name_char(c2) => {
                chars.next();
                let mut name = String::new();
                name.push(c2);
                while let Some(&c3) = chars.peek() {
                    if is_name_char(c3) {
                        name.push(c3);
                        chars.next();
                    } else {
                        break;
                    }
                }
                flush!();
                pieces.push(Piece::Group(name));
            }
            Some(_) => lit.push('$'),
        }
    }
    flush!();
    pieces
}

fn group_text(caps: &Captures, name: &str) -> String {
    if let Some(g) = caps.name(name) {
        return g.as_str().to_string();
    }
    if let Ok(idx) = name.parse::<usize>() {
        if let Some(g) = caps.get(idx) {
            return g.as_str().to_string();
        }
    }
    String::new()
}

/// Apply the replacement (limited to `limit` matches) to `name`.
pub fn get_new_name(
    name: &str,
    re: &Regex,
    pieces: &[Piece],
    limit: usize,
    transform: Option<Transform>,
) -> Option<String> {
    let mut result = String::new();
    let mut count = 0usize;
    let mut last = 0usize;
    for caps in re.captures_iter(name) {
        if limit != 0 && count >= limit {
            break;
        }
        let m = match caps.get(0) {
            Some(m) => m,
            None => break,
        };
        result.push_str(&name[last..m.start()]);
        for piece in pieces {
            match piece {
                Piece::Lit(s) => match transform {
                    Some(t) => result.push_str(&t.apply(s)),
                    None => result.push_str(s),
                },
                Piece::Group(g) => {
                    let text = group_text(&caps, g);
                    match transform {
                        Some(t) => result.push_str(&t.apply(&text)),
                        None => result.push_str(&text),
                    }
                }
            }
        }
        last = m.end();
        count += 1;
    }
    result.push_str(&name[last..]);
    if result == name {
        None
    } else {
        Some(result)
    }
}

/// Build the operation for a single path.
pub fn make_operation(path: &std::path::Path, new_name: &str) -> Operation {
    let target = match path.parent() {
        Some(parent) => parent.join(new_name),
        None => std::path::PathBuf::from(new_name),
    };
    Operation {
        source: path.to_path_buf(),
        target,
    }
}
