use std::fs;
use std::path::{Path, PathBuf};

use crate::error::RnrError;
use crate::ops::Operation;
use crate::style::{bold, bold_red, dim, green, red};

/// Split a path into its directory part (including the trailing separator) and
/// the file name.
pub fn split_path(path: &Path) -> (String, String) {
    let name = match path.file_name() {
        Some(n) => n.to_string_lossy().to_string(),
        None => path.to_string_lossy().to_string(),
    };
    let dir = match path.parent() {
        Some(parent) => {
            let s = parent.to_string_lossy().to_string();
            if s.is_empty() || s.ends_with('/') {
                s
            } else {
                format!("{}/", s)
            }
        }
        None => String::new(),
    };
    (dir, name)
}

/// Highlight which parts of the new name differ from the old one.
///
/// The algorithm walks the old name and looks for every character in the new
/// name; characters that survive are shown in green, everything else in bold
/// red.
pub fn highlight(old: &str, new: &str) -> String {
    let mut out = String::new();
    let mut kept = String::new();
    let mut pos = 0usize;
    for c in old.chars() {
        match new[pos..].find(c) {
            Some(rel) => {
                if rel > 0 {
                    if !kept.is_empty() {
                        out.push_str(&green(&kept));
                        kept.clear();
                    }
                    out.push_str(&bold_red(&new[pos..pos + rel]));
                    pos += rel;
                }
                kept.push(c);
                pos += c.len_utf8();
            }
            None => {
                if !kept.is_empty() {
                    out.push_str(&green(&kept));
                    kept.clear();
                }
            }
        }
    }
    if !kept.is_empty() {
        out.push_str(&green(&kept));
    }
    if pos < new.len() {
        out.push_str(&bold_red(&new[pos..]));
    }
    out
}

/// Print one operation.
pub fn print_operation(op: &Operation) {
    let (source_dir, source_name) = split_path(&op.source);
    let (target_dir, target_name) = split_path(&op.target);
    if !source_dir.is_empty() {
        print!("{}", dim(&source_dir));
    }
    print!("{}", dim(&source_name));
    print!(" -> ");
    if !target_dir.is_empty() {
        print!("{}", green(&target_dir));
    }
    let _ = red("");
    print!("{}", highlight(&source_name, &target_name));
    println!();
}

/// Copy `source` to a free backup path and return it.
pub fn create_backup(source: &Path) -> Result<PathBuf, RnrError> {
    let mut candidate = {
        let s = source.to_string_lossy().to_string();
        format!("{}.bk", s)
    };
    let mut index = 0usize;
    while fs::symlink_metadata(&candidate).is_ok() {
        index += 1;
        let s = source.to_string_lossy().to_string();
        candidate = format!("{}.bk.{}", s, index);
    }
    let backup = PathBuf::from(candidate);
    fs::copy(source, &backup).map_err(|e| RnrError::Rename(format!("{} -> {}", source.display(), backup.display()), e))?;
    Ok(backup)
}

/// Report a successfully created backup.
pub fn print_backup(source: &Path, backup: &Path) {
    println!(
        "{} Backup created - {}",
        bold("Info: "),
        dim(&format!("{} -> {}", source.display(), backup.display()))
    );
}
EOF
