use std::fs;
use std::path::{Path, PathBuf};

use chrono::Local;
use serde::{Deserialize, Serialize};

use crate::error::RnrError;
use crate::ops::Operation;
use crate::style::red;

#[derive(Serialize, Deserialize)]
struct DumpFile {
    date: String,
    operations: Vec<DumpOperation>,
}

#[derive(Serialize, Deserialize)]
struct DumpOperation {
    source: PathBuf,
    target: PathBuf,
}

/// Read operations from a dump file.
pub fn read(path: &Path) -> Result<Vec<Operation>, RnrError> {
    let contents = fs::read_to_string(path).map_err(|_| RnrError::OpenFile(path.to_path_buf()))?;
    let parsed: DumpFile =
        serde_json::from_str(&contents).map_err(|_| RnrError::ParseJson(path.to_path_buf()))?;
    Ok(parsed
        .operations
        .into_iter()
        .map(|o| Operation {
            source: o.source,
            target: o.target,
        })
        .collect())
}

/// Write operations to a dump file.
pub fn write(prefix: &str, operations: &[Operation]) -> Result<PathBuf, RnrError> {
    let stamp = Local::now().format("%Y-%m-%d_%H%M%S");
    let file_name = format!("{}{}.json", prefix, stamp);
    let dump = DumpFile {
        date: Local::now().format("%Y-%m-%d %H:%M:%S").to_string(),
        operations: operations
            .iter()
            .map(|o| DumpOperation {
                source: o.source.clone(),
                target: o.target.clone(),
            })
            .collect(),
    };
    let contents = serde_json::to_string_pretty(&dump).unwrap_or_default();
    let path = PathBuf::from(&file_name);
    fs::write(&path, contents.as_bytes()).map_err(|_| RnrError::CreateFile(path.clone()))?;
    Ok(path)
}
