}

/// Highlight which parts of the new name differ from the old one.
///
/// The algorithm walks the old name and looks for every character in the new
/// name; characters that survive are shown in green, everything else in bold
/// red.
pub fn highlight(old: &str, new: &str) -> String {
    let mut out = String::new();
    let mut kept = String::new();
    let mut pos = 0usize;
    for c in old.chars() {
        match new[pos..].find(c) {
            Some(rel) => {
                if rel > 0 {
                    if !kept.is_empty() {
                        out.push_str(&green(&kept));
                        kept.clear();
                    }
                    out.push_str(&bold_red(&new[pos..pos + rel]));
                    pos += rel;
                }
                kept.push(c);
                pos += c.len_utf8();
            }
            None => {
                if !kept.is_empty() {
                    out.push_str(&green(&kept));
                    kept.clear();
                }
            }
        }
    }
    if !kept.is_empty() {
        out.push_str(&green(&kept));
    }
    if pos < new.len() {
        out.push_str(&bold_red(&new[pos..]));
    }
    out
