{"command": "cat > src/main.rs <<'EOF'
mod ascii;
mod cli;
mod dump;
mod error;
mod ops;
mod output;
mod replace;
mod style;

use std::path::PathBuf;
use std::process;

use clap::ArgMatches;

use error::RnrError;
use ops::WalkOptions;
use replace::{parse_replacement, Transform};
use style::{bold, red};

#[derive(Clone, Copy, Debug, PartialEq)]
enum ColorMode {
    Always,
    Never,
    Auto,
}

fn parse_args_color(m: &ArgMatches) -> ColorMode {
    match m.get_one::<String>("color").map(|s| s.as_str()) {
        Some("always") => ColorMode::Always,
        Some("never") => ColorMode::Never,
        _ => ColorMode::Auto,
    }
}

fn apply_color(m: &ArgMatches) {
    let mode = parse_args_color(m);
    let on = match mode {
        ColorMode::Always => true,
        ColorMode::Never => false,
        ColorMode::Auto => std::io::IsTerminal::is_terminal(&std::io::stdout()),
    };
    style::set_enabled(on);
}

fn walk_options(m: &ArgMatches) -> WalkOptions {
    WalkOptions {
        recursive: m.get_flag("recursive"),
        include_dirs: m.get_flag("include-dirs"),
        hidden: m.get_flag("hidden"),
        max_depth: m.get_one::<usize>("max-depth").copied(),
    }
}

fn wants_dump(m: &ArgMatches) -> bool {
    if m.get_flag("no-dump") {
        return false;
    }
    if m.get_flag("dump") {
        return true;
    }
    m.get_flag("force")
}

fn transform_of(m: &ArgMatches) -> Option<Transform> {
    match m.get_one::<String>("replace-transform").map(|s| s.as_str()) {
        Some("upper") => Some(Transform::Upper),
        Some("lower") => Some(Transform::Lower),
        Some("ascii") => Some(Transform::Ascii),
        _ => None,
    }
}

fn report(result: Result<(), RnrError>) {
    if let Err(e) = result {
        eprintln!("{}{}", red("Error: "), e);
        process::exit(1);
    }
}

fn run_regex(m: &ArgMatches) -> Result<(), RnrError> {
    let expression = m.get_one::<String>("expression").unwrap();
    let replacement = m.get_one::<String>("replacement").unwrap();
    let re = match crate::regex::Regex::new(expression) {
        Ok(re) => re,
        Err(e) => return Err(RnrError::BadExpression(e.to_string())),
    };
    let pieces = parse_replacement(replacement);
    let limit = m.get_one::<usize>("replace-limit").copied().unwrap_or(1);
    let transform = transform_of(m);
    let paths: Vec<PathBuf> = m
        .get_many::<String>("paths")
        .map(|v| v.map(PathBuf::from).collect())
        .unwrap_or_default();
    let opts = walk_options(m);

    let collected: Vec<_> = paths
        .iter()
        .map(|p| {
            (
                p.clone(),
                crate::replace::name_for(p, &re, &pieces, limit, transform),
            )
        })
        .collect();
    let mut operations = Vec::new();
    for (path, new_name) in collected {
        if let Some(new_name) = new_name {
            operations.push(crate::replace::make_operation(&path, &new_name));
        }
    }
    let operations = ops::collect_paths(operations);

    ops::check_same_name(&operations)?;
    ops::check_existing(&operations)?;
    let operations = ops::sort_operations(operations)?;

    if m.get_flag("force") {
        if wants_dump(m) {
            dump::write(m.get_one::<String>("dump-prefix").unwrap(), &operations)?;
        }
        for op in &operations {
            if m.get_flag("backup") && !op.source.is_dir() {
                let backup = output::create_backup(&op.source)?;
                if !m.get_flag("silent") {
                    output::print_backup(&op.source, &backup);
                }
            }
            crate::ops::rename(op)?;
            if !m.get_flag("silent") {
                output::print_operation(op);
            }
        }
    } else {
        if !m.get_flag("silent") {
            println!("{}", bold("This is a DRY-RUN"));
            for op in &operations {
                output::print_operation(op);
            }
        }
        if wants_dump(m) {
            dump::write(m.get_one::<String>("dump-prefix").unwrap(), &operations)?;
        }
    }
    Ok(())
}

fn run_to_ascii(m: &ArgMatches) -> Result<(), RnrError> {
    let paths: Vec<PathBuf> = m
        .get_many::<String>("paths")
        .map(|v| v.map(PathBuf::from).collect())
        .unwrap_or_default();
    let opts = walk_options(m);
    let mut collected: Vec<(PathBuf, String)> = Vec::new();
    ops::walk_for_ascii(&paths, &opts, &mut collected);
    let mut operations = Vec::new();
    for (path, new_name) in collected {
        operations.push(crate::replace::make_operation(&path, &new_name));
    }
    let operations = ops::collect_paths(operations);
    ops::check_same_name(&operations)?;
    ops::check_existing(&operations)?;
    let operations = ops::sort_operations(operations)?;

    if m.get_flag("force") {
        if wants_dump(m) {
            dump::write(m.get_one::<String>("dump-prefix").unwrap(), &operations)?;
        }
        for op in &operations {
            if m.get_flag("backup") && !op.source.is_dir() {
                let backup = output::create_backup(&op.source)?;
                if !m.get_flag("silent") {
                    output::print_backup(&op.source, &backup);
                }
            }
            crate::ops::rename(op)?;
            if !m.get_flag("silent") {
                output::print_operation(op);
            }
        }
    } else {
        if !m.get_flag("silent") {
            println!("{}", bold("This is a DRY-RUN"));
            for op in &operations {
                output::print_operation(op);
            }
        }
        if wants_dump(m) {
            dump::write(m.get_one::<String>("dump-prefix").unwrap(), &operations)?;
        }
    }
    Ok(())
}

fn run_from_file(m: &ArgMatches) -> Result<(), RnrError> {
    let dumpfile = PathBuf::from(m.get_one::<String>("dumpfile").unwrap());
    let mut operations = dump::read(&dumpfile)?;
    if m.get_flag("undo") {
        operations.reverse();
        for op in operations.iter_mut() {
            let tmp = op.source.clone();
            op.source = op.target.clone();
            op.target = tmp;
        }
    }
    let ops = operations;
    if m.get_flag("force") {
        if wants_dump(m) {
            dump::write(m.get_one::<String>("dump-prefix").unwrap(), &ops)?;
        }
        for op in &ops {
            if m.get_flag("backup") && !op.source.is_dir() {
