cat > src/ops.rs <<'EOF'
use std::collections::HashSet;
use std::fs;
use std::path::{Path, PathBuf};

use crate::error::RnrError;

/// A single rename: `source` becomes `target`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Operation {
    pub source: PathBuf,
    pub target: PathBuf,
}

impl Operation {
    /// Compact representation used by conflict listings: `src->tgt`.
    pub fn short(&self) -> String {
        format!("{}->{}", self.source.display(), self.target.display())
    }
}

#[derive(Clone, Debug)]
pub struct WalkOptions {
    pub recursive: bool,
    pub include_dirs: bool,
    pub hidden: bool,
    pub max_depth: Option<usize>,
}

/// Depth of a path, counted as the number of components minus one.
pub fn depth_of(path: &Path) -> usize {
    path.components().count().saturating_sub(1)
}

fn is_hidden(path: &Path) -> bool {
    match path.file_name() {
        Some(name) => name.to_string_lossy().starts_with('.'),
        None => false,
    }
}

/// Depth first traversal. The visited directory itself is reported last so
/// that everything below it is processed first.
fn walk<F>(path: &Path, opts: &WalkOptions, matcher: &mut F, depth: usize, out: &mut Vec<Operation>)
where
    F: FnMut(&Path) -> Option<String>,
{
    if path.is_dir() && opts.recursive {
        let entries = match fs::read_dir(path) {
            Ok(entries) => entries,
            Err(_) => {
                push(path, opts, matcher, out);
                return;
            }
        };
        for entry in entries.flatten() {
            let child = entry.path();
            if !opts.hidden && is_hidden(&child) {
                continue;
            }
            if child.is_dir() {
                if opts.max_depth.map_or(true, |max| depth < max) {
                    walk(&child, opts, matcher, depth + 1, out);
                }
            }
            push(&child, opts, matcher, out);
        }
        push(path, opts, matcher, out);
    } else {
        push(path, opts, matcher, out);
    }
}

fn push<F>(path: &Path, opts: &WalkOptions, matcher: &mut F, out: &mut Vec<Operation>)
where
    F: FnMut(&Path) -> Option<String>,
{
    if path.is_dir() && !opts.include_dirs {
        return;
    }
    if let Some(new_name) = matcher(path) {
        let target = match path.parent() {
            Some(parent) => parent.join(new_name),
            None => PathBuf::from(new_name),
        };
        out.push(Operation {
            source: path.to_path_buf(),
            target,
        });
    }
}

/// Collect every rename operation for the given paths.
pub fn collect<F>(paths: &[PathBuf], opts: &WalkOptions, mut matcher: F) -> Vec<Operation>
where
    F: FnMut(&Path) -> Option<String>,
{
    let mut ops: Vec<Operation> = Vec::new();
    for path in paths {
        walk(path, opts, &mut matcher, 0, &mut ops);
    }
    // Deeper paths first, keeping the traversal order inside a level.
    ops.sort_by_key(|op| std::cmp::Reverse(depth_of(&op.source)));
    dedupe(ops)
}

fn dedupe(ops: Vec<Operation>) -> Vec<Operation> {
    let mut seen = HashSet::new();
    let mut result = Vec::with_capacity(ops.len());
    for op in ops {
        if seen.insert(op.source.clone()) {
            result.push(op);
        }
    }
    result
}

/// Verify that no two operations share the same target name.
pub fn check_same_name(ops: &[Operation]) -> Result<(), RnrError> {
    let mut by_target: Vec<(String, Vec<usize>)> = Vec::new();
    for (i, op) in ops.iter().enumerate() {
        let key = op.target.to_string_lossy().to_string();
        match by_target.iter_mut().find(|(k, _)| *k == key) {
            Some((_, v)) => v.push(i),
            None => by_target.push((key, vec![i])),
        }
    }
    by_target.sort_by(|a, b| a.0.cmp(&b.0));
    let mut conflicts = Vec::new();
    for (_, group) in by_target {
        if group.len() > 1 {
            let mut sources = group.clone();
            sources.sort_by(|a, b| ops[*a].source.cmp(&ops[*b].source));
            let first = ops[sources[0]].short();
            for &idx in sources.iter().skip(1) {
                conflicts.push((first.clone(), ops[idx].short()));
            }
        }
    }
    if conflicts.is_empty() {
        Ok(())
    } else {
        Err(RnrError::SameName(conflicts))
    }
}

/// Verify that targets do not collide with paths that already exist and that
/// are not going to be renamed away.
pub fn check_existing(ops: &[Operation]) -> Result<(), RnrError> {
    let sources: HashSet<String> = ops
        .iter()
        .map(|op| op.source.to_string_lossy().to_string())
        .collect();
    for op in ops {
        let target = op.target.to_string_lossy().to_string();
        if fs::symlink_metadata(&op.target).is_ok() && !sources.contains(&target) {
            return Err(RnrError::Conflict(op.clone()));
        }
    }
    Ok(())
}

/// Order operations so that renaming them in sequence never fails because the
/// target of one operation is still the source of a pending one.
pub fn sort_operations(ops: Vec<Operation>) -> Result<Vec<Operation>, RnrError> {
    let mut pending: Vec<Operation> = ops;
    let mut result: Vec<Operation> = Vec::with_capacity(pending.len());
    while !pending.is_empty() {
        let sources: HashSet<String> = pending
            .iter()
            .map(|op| op.source.to_string_lossy().to_string())
            .collect();
        let mut round = Vec::new();
        let mut rest = Vec::new();
        for op in pending {
            let target = op.target.to_string_lossy().to_string();
            if sources.contains(&target) {
                rest.push(op);
            } else {
                round.push(op);
            }
        }
        if round.is_empty() {
            return Err(RnrError::SortingProblem);
        }
        result.extend(round);
        pending = rest;
    }
    Ok(result)
}

/// Perform a rename, reporting failures.
pub fn rename(op: &Operation) -> Result<(), RnrError> {
    fs::rename(&op.source, &op.target).map_err(|e| {
        RnrError::Rename(
            format!("{} -> {}", op.source.display(), op.target.display()),
            e,
        )
    })
}
