def tree(d):
    out=[]
    for root,dirs,files in os.walk(d):
        for f in sorted(files):
            if f.startswith('rnr-') and f.endswith('.json'): continue
            p=os.path.relpath(os.path.join(root,f),d)
            out.append(p)
        for dd in sorted(dirs):
            p=os.path.relpath(os.path.join(root,dd),d)
            out.append(p+'/')
    return sorted(out)
def run(binary, cwd, args):
    p=subprocess.run([binary]+args,cwd=cwd,capture_output=True)
    return p.stdout.decode('utf8','replace'),p.stderr.decode('utf8','replace'),p.returncode
def compare(name,setup,args,quiet=False):
    A='/tmp/_cmpA'; B='/tmp/_cmpB'
    for d in (A,B):
        shutil.rmtree(d,ignore_errors=True); os.makedirs(d)
        subprocess.run(['bash','-c',setup],cwd=d,capture_output=True)
    soa,sea,rca=run(MINE,A,args)
    sob,seb,rcb=run(ORIG,B,args)
    ta,tb=tree(A),tree(B)
    dumps=[]
    for d,tag in ((A,'A'),(B,'B')):
