    # normalize dump json dates
    def norm(s):
        s=re.sub(r'"date": "[^"]*"','"date": "X"',s)
        s=re.sub(r'rnr-[^"]*\.json','DUMP.json',s)
        return s
    ok2 = norm(''.join(sorted(dumps)))==norm(''.join(sorted(dumps)))
    ok = ok and ok2
    if ok:
        if not quiet: print('SAME: %s | %s'%(name,args))
    else:
        print('DIFF: %s | %s'%(name,args))
        if soa!=sob:
