import os,subprocess,sys
BIN='/workspace/executable'
DIR='/tmp/ascii_probe'
def probe_batch(cps):
    """cps: list of codepoints. Returns dict cp->ascii str."""
    tags={}
    name=[]
    for cp in cps:
        t='Z%04x_'%cp if cp<0x10000 else 'Z%05x_'%cp
        tags[cp]=t
        name.append(t+chr(cp))
    fn=''.join(name)
    assert len(fn.encode())<250, len(fn.encode())
    open(os.path.join(DIR,fn),'w').close()
    p=subprocess.run([BIN,'to-ascii',fn],cwd=DIR,capture_output=True,text=True)
    lines=[l for l in p.stdout.split('\n') if l and 'DRY' not in l]
    if not lines:
        raise Exception('no output for batch: '+p.stderr[:200]+' src='+repr(fn[:80]))
    line=lines[0]
    tgt=line.split(' -> ',1)[1]
    # parse tags in order
    res={}
    pos=0
    for i,cp in enumerate(cps):
        t=tags[cp]
        idx=tgt.find(t,pos)
        if idx<0: raise Exception('tag %s not found in %r'%(t,tgt[:200]))
        end=None
        if i+1<len(cps):
            end=tgt.find(tags[cps[i+1]],idx+len(t))
            if end<0: raise Exception('next tag not found')
        else:
            end=len(tgt)
        res[cp]=tgt[idx+len(t):end]
        pos=end
    return res
if __name__=='__main__':
    os.makedirs(DIR,exist_ok=True)
    print(probe_batch([0xe9,0xf1,0x4e2d,0x1f600]))
